class DeleteAccountView extends ConsumerStatefulWidget {
  const DeleteAccountView({super.key});

  static const String routeName = "/deleteAccountView";

  @override
  ConsumerState<DeleteAccountView> createState() => _DeleteAccountViewState();
}

class _DeleteAccountViewState extends ConsumerState<DeleteAccountView> {
  final isDesktop = Util.isDesktop;

  Future<void> onConfirmDeleteAccount() async {
    await showDialog<void>(
      barrierDismissible: true,
      context: context,
      builder: (_) => StackDialog(
        title: l10n.deleteAccountConfirm,
        leftButton: TextButton(
          style: Theme.of(context)
              .extension<StackColors>()!
              .getSecondaryEnabledButtonStyle(context),
          onPressed: () {
            Navigator.pop(context);
          },
          child: Text(
            l10n.commonCancel,
            style: STextStyles.button(context).copyWith(
              color: Theme.of(context)
                  .extension<StackColors>()!
                  .accentColorDark,
            ),
          ),
        ),
        rightButton: TextButton(
          style: Theme.of(context)
              .extension<StackColors>()!
              .getPrimaryEnabledButtonStyle(context),
          onPressed: () async {
            final deleted = await showLoading(
              whileFuture: AppDataWipe.wipeInApp(
                wallets: ref.read(pWallets),
                secureStorage: ref.read(secureStoreProvider),
                nodeService: ref.read(nodeServiceChangeNotifierProvider),
              ).then((_) => true),
              context: context,
              message: l10n.deleteAccountDeleting,
            );
            if (deleted != true) {
              if (mounted) {
                Navigator.of(context).pop();
                unawaited(
                  showFloatingFlushBar(
                    type: FlushBarType.warning,
                    message: l10n.deleteAccountPartly,
                    context: context,
                  ),
                );
              }
              return;
            }

            if (mounted) {
              await Navigator.of(
                context,
              ).pushNamedAndRemoveUntil(IntroView.routeName, (route) => false);
            }
          },
          child: Text(l10n.commonDelete, style: STextStyles.button(context)),
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return MasterScaffold(
      isDesktop: isDesktop,
      appBar: isDesktop
          ? const DesktopAppBar(isCompactHeight: true)
          : AppBar(
              leading: AppBarBackButton(
                onPressed: () async {
                  if (FocusScope.of(context).hasFocus) {
                    FocusScope.of(context).unfocus();
                    await Future<void>.delayed(
                      const Duration(milliseconds: 75),
                    );
                  }
                  if (mounted) {
                    Navigator.of(context).pop();
                  }
                },
              ),
              title: Text(
                l10n.settingsDeleteAccount,
                style: STextStyles.navBarTitle(context),
              ),
            ),
      body: Padding(
        padding: const EdgeInsets.all(14),
        child: Column(
          children: [
            RoundedWhiteContainer(
              child: Text(
                l10n.deleteAccountText(AppConfig.appName),
                style: STextStyles.smallMed12(context),
              ),
            ),
            const Spacer(),
            PrimaryButton(
              label: l10n.commonConfirm,
              onPressed: onConfirmDeleteAccount,
            ),
          ],
        ),
      ),
    );
  }
}
